async function exercise(){
 const gpu=navigator.gpu;
 if(!gpu)return {stage:'navigator',ok:false};
 const adapter=await gpu.requestAdapter({powerPreference:'high-performance',forceFallbackAdapter:false});
 if(!adapter)return {stage:'adapter',ok:false};
 const info=Object.fromEntries(['vendor','architecture','device','description'].map(k=>[k,adapter.info[k]]));
 const device=await adapter.requestDevice();const buffers=[];let stage='device';
 try{
  device.pushErrorScope('validation');
  const make=(size,usage)=>{const b=device.createBuffer({size,usage});buffers.push(b);return b;};
  const a=make(1024,GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_DST|GPUBufferUsage.COPY_SRC);
  const read=make(1024,GPUBufferUsage.MAP_READ|GPUBufferUsage.COPY_DST);
  device.queue.writeBuffer(a,0,Uint32Array.from({length:256},(_,i)=>i));stage='shader';
  const module=device.createShaderModule({code:'@group(0) @binding(0) var<storage,read_write> a:array<u32>; @compute @workgroup_size(64) fn main(@builtin(global_invocation_id) id:vec3<u32>){a[id.x]=a[id.x]*3u+7u;}'});
  const messages=(await module.getCompilationInfo()).messages.map(m=>({type:m.type,message:m.message}));
  const pipeline=await device.createComputePipelineAsync({layout:'auto',compute:{module,entryPoint:'main'}});
  const group=device.createBindGroup({layout:pipeline.getBindGroupLayout(0),entries:[{binding:0,resource:{buffer:a}}]});
  const encoder=device.createCommandEncoder();const pass=encoder.beginComputePass();pass.setPipeline(pipeline);pass.setBindGroup(0,group);pass.dispatchWorkgroups(4);pass.end();encoder.copyBufferToBuffer(a,0,read,0,1024);stage='submit';
  device.queue.submit([encoder.finish()]);await device.queue.onSubmittedWorkDone();stage='readback';await read.mapAsync(GPUMapMode.READ);
  const values=Array.from(new Uint32Array(read.getMappedRange()));read.unmap();const error=await device.popErrorScope();
  return {ok:!error&&values.every((x,i)=>x===i*3+7),stage:'complete',adapter:info,values,messages,validationError:error?.message??null,apiFunction:String(gpu.requestAdapter)};
 }catch(e){return {ok:false,stage,adapter:info,error:String(e)};}finally{buffers.forEach(b=>b.destroy());device.destroy();}
}
